// src/pages/CreerCours.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './CreerCours.css';

function CreerCours() {
  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    matiere: '',
    niveau: 'débutant',
    estPublic: true,
    fichierCours: null
  });
  const [isLoading, setIsLoading] = useState(false);
  const [filePreview, setFilePreview] = useState(null);
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    
    if (type === 'file') {
      const file = files[0];
      setFormData(prev => ({
        ...prev,
        fichierCours: file
      }));

      if (file) {
        setFilePreview({
          name: file.name,
          size: (file.size / (1024 * 1024)).toFixed(2),
          type: file.type
        });
      } else {
        setFilePreview(null);
      }
    } else if (type === 'checkbox') {
      setFormData(prev => ({
        ...prev,
        [name]: checked
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    // Validation
    if (!formData.titre || !formData.description || !formData.matiere) {
      alert('Veuillez remplir tous les champs obligatoires (*)');
      setIsLoading(false);
      return;
    }

    const token = localStorage.getItem('token');
    if (!token) {
      alert('Vous devez être connecté pour créer un cours');
      navigate('/login');
      return;
    }

    try {
      // Créer FormData pour l'upload
      const submitData = new FormData();
      submitData.append('titre', formData.titre);
      submitData.append('description', formData.description);
      submitData.append('matiere', formData.matiere);
      submitData.append('niveau', formData.niveau);
      submitData.append('estPublic', formData.estPublic);
      
      if (formData.fichierCours) {
        submitData.append('fichier', formData.fichierCours);
      }

      console.log('📤 Envoi des données à l\'API...');
      
      // Appel API réel
      const res = await axios.post('http://localhost:5000/api/courses', submitData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      console.log('✅ Réponse API:', res.data);
      alert('Cours créé avec succès !');
      navigate('/dashboard-prof');
      
    } catch (err) {
      console.error('❌ Erreur API:', err);
      
      let errorMessage = 'Erreur lors de la création du cours';
      
      if (err.response) {
        // Erreur du serveur
        console.log('📊 Statut:', err.response.status);
        console.log('📄 Données erreur:', err.response.data);
        
        errorMessage = err.response.data?.message || 
                      err.response.data?.error || 
                      `Erreur ${err.response.status}`;
      } else if (err.request) {
        // Pas de réponse du serveur
        errorMessage = 'Le serveur ne répond pas. Vérifiez que le backend est démarré.';
      }
      
      alert(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    if (window.confirm('Voulez-vous vraiment annuler ? Les modifications seront perdues.')) {
      navigate('/dashboard-prof');
    }
  };

  const getFileIcon = (fileType) => {
    if (fileType.includes('pdf')) return '📕';
    if (fileType.includes('word') || fileType.includes('document')) return '📄';
    if (fileType.includes('powerpoint') || fileType.includes('presentation')) return '📊';
    if (fileType.includes('zip') || fileType.includes('rar')) return '📦';
    return '📁';
  };

  return (
    <div className="creer-cours-container">
      <div className="creer-cours-card">
        <div className="creer-cours-header">
          <button className="back-btn" onClick={handleCancel}>
            ← Retour
          </button>
          <h1>Créer un nouveau cours</h1>
          <p>Remplissez les informations pour créer votre cours</p>
        </div>

        <form onSubmit={handleSubmit} className="creer-cours-form">
          <div className="form-sections">
            {/* Section Informations de base */}
            <div className="form-section">
              <h2>Informations de base</h2>
              
              <div className="form-group">
                <label htmlFor="titre">Titre du cours *</label>
                <input
                  id="titre"
                  type="text"
                  name="titre"
                  value={formData.titre}
                  onChange={handleInputChange}
                  placeholder="Ex: Mathématiques Avancées, Physique Quantique..."
                  required
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label htmlFor="description">Description *</label>
                <textarea
                  id="description"
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  placeholder="Décrivez le contenu de votre cours, les objectifs d'apprentissage, etc."
                  required
                  rows="4"
                  className="form-textarea"
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="matiere">Matière *</label>
                  <select
                    id="matiere"
                    name="matiere"
                    value={formData.matiere}
                    onChange={handleInputChange}
                    required
                    className="form-select"
                  >
                    <option value="">Sélectionnez une matière</option>
                    <option value="mathématiques">Mathématiques</option>
                    <option value="physique">Physique</option>
                    <option value="chimie">Chimie</option>
                    <option value="informatique">Informatique</option>
                    <option value="biologie">Biologie</option>
                    <option value="français">Français</option>
                    <option value="anglais">Anglais</option>
                    <option value="histoire">Histoire</option>
                    <option value="philosophie">Philosophie</option>
                    <option value="économie">Économie</option>
                    <option value="autres">Autres</option>
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="niveau">Niveau *</label>
                  <select
                    id="niveau"
                    name="niveau"
                    value={formData.niveau}
                    onChange={handleInputChange}
                    required
                    className="form-select"
                  >
                    <option value="débutant">Débutant</option>
                    <option value="intermédiaire">Intermédiaire</option>
                    <option value="avancé">Avancé</option>
                    <option value="expert">Expert</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Section Fichier du cours */}
            <div className="form-section">
              <h2>Fichier du cours</h2>
              
              <div className="form-group">
                <label>Fichier du cours (PDF, Word, PowerPoint, ZIP)</label>
                <div className="file-upload-container">
                  <div className="file-preview">
                    {filePreview ? (
                      <div className="file-info">
                        <span className="file-icon">{getFileIcon(filePreview.type)}</span>
                        <div className="file-details">
                          <h4>{filePreview.name}</h4>
                          <p>{filePreview.size} MB</p>
                        </div>
                      </div>
                    ) : (
                      <div className="file-placeholder">
                        <span>📁</span>
                        <p>Aucun fichier sélectionné</p>
                        <small>Formats acceptés: PDF, DOC, DOCX, PPT, PPTX, ZIP</small>
                      </div>
                    )}
                  </div>
                  <label htmlFor="file-upload" className="file-upload-btn">
                    📎 Choisir un fichier
                  </label>
                  <input
                    id="file-upload"
                    type="file"
                    name="fichierCours"
                    accept=".pdf,.doc,.docx,.ppt,.pptx,.zip,.rar"
                    onChange={handleInputChange}
                    className="file-input"
                  />
                </div>
              </div>

              <div className="form-group">
                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    name="estPublic"
                    checked={formData.estPublic}
                    onChange={handleInputChange}
                    className="checkbox-input"
                  />
                  <span className="checkmark"></span>
                  Cours public
                </label>
                <small>Si désactivé, le cours sera privé et accessible par lien uniquement</small>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="form-actions">
            <button 
              type="button" 
              className="cancel-btn"
              onClick={handleCancel}
            >
              Annuler
            </button>
            <button 
              type="submit" 
              className="submit-btn"
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <span className="spinner"></span>
                  Création en cours...
                </>
              ) : (
                'Créer le cours'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default CreerCours;
